import{_ as n,o as s,c as e,a2 as l}from"./chunks/framework.XXezeKOl.js";const g=JSON.parse('{"title":"Chain-of-Thought","description":"精读 Chain-of-Thought Prompting：在示例里写出推理步骤，就能让大模型的多步推理能力显著提升。","frontmatter":{"title":"Chain-of-Thought","description":"精读 Chain-of-Thought Prompting：在示例里写出推理步骤，就能让大模型的多步推理能力显著提升。"},"headers":[],"relativePath":"papers/chain-of-thought.md","filePath":"papers/chain-of-thought.md","lastUpdated":null}'),t={name:"papers/chain-of-thought.md"};function i(o,a,r,p,h,u){return s(),e("div",null,[...a[0]||(a[0]=[l(`<h1 id="chain-of-thought" tabindex="-1">Chain-of-Thought <a class="header-anchor" href="#chain-of-thought" aria-label="Permalink to &quot;Chain-of-Thought&quot;">​</a></h1><h2 id="论文信息" tabindex="-1">论文信息 <a class="header-anchor" href="#论文信息" aria-label="Permalink to &quot;论文信息&quot;">​</a></h2><ul><li>标题：Chain-of-Thought Prompting Elicits Reasoning in Large Language Models</li><li>作者：Jason Wei、Xuezhi Wang、Dale Schuurmans、Maarten Bosma、Brian Ichter、Fei Xia、Ed Chi、Quoc Le、Denny Zhou（Google）</li><li>年份：2022（NeurIPS 2022）</li><li>链接：<a href="https://arxiv.org/abs/2201.11903" target="_blank" rel="noreferrer">arXiv:2201.11903</a></li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p>在 Few-shot 示例中不只给&quot;问题 → 答案&quot;，而是给&quot;问题 → 推理过程 → 答案&quot;，足够大的模型就会模仿着先推理再作答，从而在数学、常识和符号推理任务上明显变好。</p><h2 id="要解决的问题" tabindex="-1">要解决的问题 <a class="header-anchor" href="#要解决的问题" aria-label="Permalink to &quot;要解决的问题&quot;">​</a></h2><p>当时的大模型在&quot;一步就能答&quot;的任务上表现不错，但在需要多步推理的任务上，比如数学应用题，表现很差，而且单纯把模型做大带来的提升也有限。</p><p>之前的改进方法要么需要大量人工标注的推理过程去微调模型，要么需要专门训练一个验证器，成本都很高。作者想知道：能不能只改提示词，不改模型，就把推理能力&quot;引出来&quot;？</p><h2 id="核心方法" tabindex="-1">核心方法 <a class="header-anchor" href="#核心方法" aria-label="Permalink to &quot;核心方法&quot;">​</a></h2><p>方法本身非常简单：把 Few-shot 示例里的答案换成&quot;推理步骤加答案&quot;。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>标准 Few-shot 提示                        Chain-of-Thought 提示</span></span>
<span class="line"><span>┌─────────────────────────────────┐      ┌──────────────────────────────────────────┐</span></span>
<span class="line"><span>│ Q: 罗杰有 5 个网球，又买了 2 罐， │      │ Q: 罗杰有 5 个网球，又买了 2 罐，          │</span></span>
<span class="line"><span>│    每罐 3 个，他现在有几个？      │      │    每罐 3 个，他现在有几个？               │</span></span>
<span class="line"><span>│ A: 11                           │      │ A: 罗杰一开始有 5 个。2 罐每罐 3 个，      │</span></span>
<span class="line"><span>│                                 │      │    共 6 个。5 + 6 = 11。答案是 11。        │</span></span>
<span class="line"><span>│ Q: &lt;新问题&gt;                      │      │ Q: &lt;新问题&gt;                               │</span></span>
<span class="line"><span>│ A: ?                            │      │ A: ?                                     │</span></span>
<span class="line"><span>└─────────────────────────────────┘      └──────────────────────────────────────────┘</span></span>
<span class="line"><span>          │                                              │</span></span>
<span class="line"><span>          ▼                                              ▼</span></span>
<span class="line"><span>   模型直接猜答案，容易错                       模型先写出中间步骤，再得出答案</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>要点：</p><ul><li>不需要训练，只需要手写几个（论文里大约 8 个）带推理过程的示例。</li><li>推理步骤用自然语言写，人可以读懂，也便于排查模型错在哪一步。</li><li>同一套示例可以复用到同类任务上。</li></ul><h2 id="关键实验结论" tabindex="-1">关键实验结论 <a class="header-anchor" href="#关键实验结论" aria-label="Permalink to &quot;关键实验结论&quot;">​</a></h2><p>论文在算术推理（如 GSM8K 数学应用题）、常识推理和符号推理（如字母拼接、硬币翻转）三类任务上做了实验，主要结论：</p><ul><li><strong>思维链是一种随规模涌现的能力。</strong> 在较小的模型上，思维链提示几乎没有帮助，甚至会生成看似通顺但逻辑错误的推理；只有在模型规模足够大时，提升才明显。</li><li><strong>任务越复杂，收益越大。</strong> 在一步就能完成的简单题上提升有限，在多步推理题上提升显著。</li><li><strong>在 GSM8K 上，最大的模型配合思维链提示，达到了当时的最好水平</strong>，超过了此前经过微调的方法。</li><li><strong>消融实验说明推理的内容本身很重要。</strong> 只让模型输出公式、只输出与推理等长的无意义字符、或者先给答案再写推理，效果都不如完整的思维链。这说明提升不只是来自&quot;多生成了一些 Token&quot;。</li></ul><h2 id="对-agent-开发的启发" tabindex="-1">对 Agent 开发的启发 <a class="header-anchor" href="#对-agent-开发的启发" aria-label="Permalink to &quot;对 Agent 开发的启发&quot;">​</a></h2><ul><li><strong>&quot;先想再做&quot;是 Agent 的基本结构。</strong> ReAct 中的 Thought、各种 Agent 框架中的规划步骤，都可以看成思维链在行动场景下的延伸。</li><li><strong>推理过程是调试信息。</strong> 让模型把中间步骤写出来，出错时你能定位是哪一步理解错了，这对 Agent 的可观测性非常有价值。</li><li><strong>示例比指令更有说服力。</strong> 想让模型按某种方式思考，最直接的办法是给它看几个这样思考的例子。</li><li><strong>要区分对待推理模型。</strong> 今天的推理模型在内部已经做了类似的事，再在提示词里强制要求&quot;一步一步想&quot;可能收益不大，甚至增加延迟和成本。参考 <a href="/guide/02-llm-basics/reasoning-models">推理模型与扩展思考</a>。</li></ul><h2 id="局限性" tabindex="-1">局限性 <a class="header-anchor" href="#局限性" aria-label="Permalink to &quot;局限性&quot;">​</a></h2><ul><li>推理过程写出来不代表它就是模型&quot;真实的&quot;推理依据，推理和答案可能不一致。</li><li>推理链可能看起来很合理但结论是错的，不能把它当成正确性的保证。</li><li>需要人工写示例，示例的质量和风格会影响结果。</li><li>输出更长，意味着更高的延迟和 Token 成本。</li><li>结论依赖当时的模型规模，在今天的模型上提升幅度可能不同。</li></ul><p>后续工作 Self-Consistency（多次采样思维链再投票）和 Zero-shot CoT（只加一句&quot;让我们一步一步思考&quot;）进一步降低了使用门槛，<a href="/papers/tree-of-thoughts">Tree of Thoughts</a> 则把单条推理链扩展成了树搜索。</p><h2 id="相关文章" tabindex="-1">相关文章 <a class="header-anchor" href="#相关文章" aria-label="Permalink to &quot;相关文章&quot;">​</a></h2><ul><li><a href="/guide/04-prompt/few-shot-cot">Few-shot 与思维链</a></li><li><a href="/guide/02-llm-basics/reasoning-models">推理模型与扩展思考</a></li><li><a href="/guide/04-prompt/basics">提示词基本原则</a></li><li><a href="/guide/06-agent-loop/react">ReAct：推理与行动</a></li></ul>`,23)])])}const d=n(t,[["render",i]]);export{g as __pageData,d as default};
